<script setup lang="ts">
import {computed} from 'vue'
import {ArrowLeft,LayoutGrid,RefreshCw,TriangleAlert} from '@lucide/vue'
import './theme.css'
const props=withDefaults(defineProps<{kind?:'loading'|'error';appName?:string;portalUrl?:string}>(),{kind:'loading',appName:'个人空间',portalUrl:'/'})
const theme=(()=>{try{const value=localStorage.getItem('personal-portal-theme');return value==='light'||value==='dark'?value:'system'}catch{return 'system'}})()
const heading=computed(()=>props.kind==='error'?'页面暂时没有打开':`正在打开${props.appName}`)
function reload(){window.location.reload()}
</script>
<template><main class="personal-portal platform-page-state" :class="`portal-${theme}`"><a class="page-state-brand" :href="portalUrl"><LayoutGrid :size="20"/>我的空间</a><section :role="kind==='error'?'alert':'status'" :aria-busy="kind==='loading'"><span class="page-state-icon"><TriangleAlert v-if="kind==='error'" :size="27"/><RefreshCw v-else :size="25" class="page-state-spin"/></span><small>{{ kind==='error'?'请稍后重试':'正在准备应用' }}</small><h1>{{ heading }}</h1><p>{{ kind==='error'?'页面文件加载失败，或显示内容时发生异常。可以重新加载，也可以返回门户打开其他应用。':'正在加载页面与交互组件，请稍候。' }}</p><template v-if="kind==='error'"><p class="page-state-note">重新加载不会清空本地账本或修改账号数据。</p><div class="page-state-actions"><button type="button" @click="reload"><RefreshCw :size="16"/>重新加载页面</button><a :href="portalUrl"><ArrowLeft :size="15"/>返回门户</a></div></template><div v-else class="page-state-skeleton" aria-hidden="true"><i/><i/><i/></div></section></main></template>
